package jadx.permdb;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

import org.jetbrains.annotations.Nullable;

/**
 * Parse {@code android-stubs-src.jar} of an SDK platform (generated by metalava, without javadoc).
 * Collects what the annotations don't contain: values of String constants (inlined in app code),
 * {@code android.net.Uri} fields (content URIs) and super classes.
 */
final class StubsParser {

	private static final Pattern PACKAGE = Pattern.compile("^package\\s+([\\w.]+)\\s*;");
	private static final Pattern TYPE_DECL = Pattern.compile(
			"\\b(class|interface|enum|@interface)\\s+(\\w+)(?:\\s*<[^{]*?>)?(?:\\s+extends\\s+([\\w.]+))?");
	private static final Pattern STRING_CONST = Pattern.compile(
			"\\bstatic\\s+final\\s+java\\.lang\\.String\\s+(\\w+)\\s*=\\s*\"((?:[^\"\\\\]++|\\\\.)*+)\"\\s*;");
	private static final Pattern URI_FIELD = Pattern.compile("\\bstatic\\s+final\\s+android\\.net\\.Uri\\s+(\\w+)\\s*;");
	private static final String BROADCAST_CONSTANT = "SdkConstantType.BROADCAST_INTENT_ACTION";

	/** binary class name + '.' + field name -> value */
	private final Map<String, String> constants = new HashMap<>();
	/** binary class name -> Uri fields */
	private final Map<String, List<String>> uriFields = new HashMap<>();
	/** binary class name -> binary super class name */
	private final Map<String, String> superClasses = new HashMap<>();
	/** values of constants marked as broadcast intent actions */
	private final Set<String> broadcastActions = new HashSet<>();

	static StubsParser parseJar(byte[] jar) throws IOException {
		StubsParser parser = new StubsParser();
		try (ZipInputStream zip = new ZipInputStream(new ByteArrayInputStream(jar))) {
			ZipEntry entry;
			while ((entry = zip.getNextEntry()) != null) {
				if (entry.getName().endsWith(".java")) {
					parser.parseSource(new String(zip.readAllBytes(), StandardCharsets.UTF_8));
				}
			}
		}
		return parser;
	}

	private static final class TypeScope {
		final String binaryName;
		final int depth;

		TypeScope(String binaryName, int depth) {
			this.binaryName = binaryName;
			this.depth = depth;
		}
	}

	void parseSource(String source) {
		String pkg = "";
		Deque<TypeScope> scopes = new ArrayDeque<>();
		String pendingType = null;
		int depth = 0;
		boolean inBlockComment = false;
		for (String line : source.split("\n")) {
			String code = stripComments(line, inBlockComment);
			inBlockComment = endsInBlockComment(line, inBlockComment);
			if (code.isBlank()) {
				continue;
			}
			Matcher pkgMatcher = PACKAGE.matcher(code);
			if (pkgMatcher.find()) {
				pkg = pkgMatcher.group(1);
				continue;
			}
			String currentType = scopes.isEmpty() ? null : scopes.peek().binaryName;
			Matcher typeMatcher = TYPE_DECL.matcher(removeStrings(code));
			if (typeMatcher.find()) {
				String name = typeMatcher.group(2);
				pendingType = currentType == null ? (pkg.isEmpty() ? name : pkg + '.' + name) : currentType + '$' + name;
				String superCls = typeMatcher.group(3);
				if (superCls != null && typeMatcher.group(1).equals("class")) {
					superClasses.put(pendingType, JavaNames.toBinaryName(superCls));
				}
			} else if (currentType != null && depth == scopes.peek().depth) {
				parseMember(currentType, code);
			}
			String braces = removeStrings(code);
			for (int i = 0; i < braces.length(); i++) {
				char c = braces.charAt(i);
				if (c == '{') {
					depth++;
					if (pendingType != null) {
						scopes.push(new TypeScope(pendingType, depth));
						pendingType = null;
					}
				} else if (c == '}') {
					if (!scopes.isEmpty() && scopes.peek().depth == depth) {
						scopes.pop();
					}
					depth--;
				}
			}
		}
	}

	private void parseMember(String cls, String code) {
		Matcher constMatcher = STRING_CONST.matcher(code);
		if (constMatcher.find()) {
			String value = unescape(constMatcher.group(2));
			constants.put(cls + '.' + constMatcher.group(1), value);
			if (code.contains(BROADCAST_CONSTANT)) {
				broadcastActions.add(value);
			}
			return;
		}
		Matcher uriMatcher = URI_FIELD.matcher(code);
		if (uriMatcher.find()) {
			uriFields.computeIfAbsent(cls, c -> new ArrayList<>()).add(uriMatcher.group(1));
		}
	}

	private static String stripComments(String line, boolean inBlockComment) {
		String s = line;
		if (inBlockComment) {
			int end = s.indexOf("*/");
			if (end == -1) {
				return "";
			}
			s = s.substring(end + 2);
		}
		int start = s.indexOf("/*");
		while (start != -1) {
			int end = s.indexOf("*/", start + 2);
			if (end == -1) {
				s = s.substring(0, start);
				break;
			}
			s = s.substring(0, start) + s.substring(end + 2);
			start = s.indexOf("/*");
		}
		int lineComment = s.indexOf("//");
		if (lineComment != -1 && !s.substring(0, lineComment).contains("\"")) {
			s = s.substring(0, lineComment);
		}
		return s;
	}

	private static boolean endsInBlockComment(String line, boolean inBlockComment) {
		boolean in = inBlockComment;
		int pos = 0;
		while (true) {
			int next = line.indexOf(in ? "*/" : "/*", pos);
			if (next == -1) {
				return in;
			}
			in = !in;
			pos = next + 2;
		}
	}

	/**
	 * Replace string and char literals content (may contain braces or keywords)
	 */
	static String removeStrings(String code) {
		StringBuilder sb = new StringBuilder(code.length());
		char quote = 0;
		for (int i = 0; i < code.length(); i++) {
			char c = code.charAt(i);
			if (quote != 0) {
				if (c == '\\') {
					i++;
				} else if (c == quote) {
					quote = 0;
					sb.append(c);
				}
				continue;
			}
			if (c == '"' || c == '\'') {
				quote = c;
			}
			sb.append(c);
		}
		return sb.toString();
	}

	static String unescape(String str) {
		if (str.indexOf('\\') == -1) {
			return str;
		}
		StringBuilder sb = new StringBuilder(str.length());
		for (int i = 0; i < str.length(); i++) {
			char c = str.charAt(i);
			if (c != '\\' || i + 1 >= str.length()) {
				sb.append(c);
				continue;
			}
			char n = str.charAt(++i);
			switch (n) {
				case 'n':
					sb.append('\n');
					break;
				case 't':
					sb.append('\t');
					break;
				case 'r':
					sb.append('\r');
					break;
				case 'u':
					if (i + 4 < str.length()) {
						sb.append((char) Integer.parseInt(str.substring(i + 1, i + 5), 16));
						i += 4;
					}
					break;
				default:
					sb.append(n);
					break;
			}
		}
		return sb.toString();
	}

	@Nullable
	String getConstant(String cls, String field) {
		return constants.get(cls + '.' + field);
	}

	Map<String, List<String>> getUriFields() {
		return uriFields;
	}

	@Nullable
	String getSuperClass(String cls) {
		return superClasses.get(cls);
	}

	Set<String> getBroadcastActions() {
		return broadcastActions;
	}

	/**
	 * Binary name of the String constant field with this value (first found, sorted by name)
	 */
	@Nullable
	String findConstantField(String value) {
		String found = null;
		for (Map.Entry<String, String> entry : constants.entrySet()) {
			if (entry.getValue().equals(value) && (found == null || entry.getKey().compareTo(found) < 0)) {
				found = entry.getKey();
			}
		}
		return found;
	}
}
